/*
 * Add cache to configuration, adding fonts and directories
 */

FcBool
FcConfigAddCache (FcConfig *config, FcCache *cache,
                  FcSetName set, FcStrSet *dirSet, FcChar8 *forDir)
{
    FcFontSet *fs;
    intptr_t  *dirs;
    int        i;
    FcBool     relocated = FcFalse;

    if (strcmp ((char *)FcCacheDir (cache), (char *)forDir) != 0)
	relocated = FcTrue;

    /*
     * Add fonts
     */
    fs = FcCacheSet (cache);
    if (fs) {
	int nref = 0;

	for (i = 0; i < fs->nfont; i++) {
	    FcPattern *font = FcFontSetFont (fs, i);
	    FcChar8   *font_file;
	    FcChar8   *relocated_font_file = NULL;

	    if (FcPatternObjectGetString (font, FC_FILE_OBJECT,
	                                  0, &font_file) == FcResultMatch) {
		if (relocated) {
		    FcChar8 *slash = FcStrLastSlash (font_file);
		    relocated_font_file = FcStrBuildFilename (forDir, slash + 1, NULL);
		    font_file = relocated_font_file;
		}

		/*
		 * Check to see if font is banned by filename
		 */
		if (!FcConfigAcceptFilename (config, font_file)) {
		    free (relocated_font_file);
		    continue;
		}
	    }

	    /*
	     * Check to see if font is banned by pattern
	     */
	    if (!FcConfigAcceptFont (config, font)) {
		free (relocated_font_file);
		continue;
	    }

	    /*
	     * Check to see if font is banned by client
	     */
	    if (!FcConfigAcceptFilter (config, font)) {
		free (relocated_font_file);
		continue;
	    }
	    if (relocated_font_file) {
		font = FcPatternCacheRewriteFile (font, cache, relocated_font_file);
		free (relocated_font_file);
	    }

	    if (FcFontSetAdd (config->fonts[set], font))
		nref++;
	}
	FcDirCacheReference (cache, nref);
    }

    /*
     * Add directories
     */
    dirs = FcCacheDirs (cache);
    if (dirs) {
	for (i = 0; i < cache->dirs_count; i++) {
	    const FcChar8 *dir = FcCacheSubdir (cache, i);
	    FcChar8       *s = NULL;

	    if (relocated) {
		FcChar8 *base = FcStrBasename (dir);
		FcChar8 *p;
		p = FcStrBuildFilename (forDir, base, NULL);
		dir = s = FcStrCopyFilename (p);
		FcStrFree (p);
		FcStrFree (base);
	    }
    }

    FcLangSetDestroy (ls);

    if (spacing != FC_SPACING_PROPORTIONAL)
	if (!FcPatternObjectAddInteger (pat, FC_SPACING_OBJECT, spacing))
	    goto bail2;

    if (!(face->face_flags & FT_FACE_FLAG_SCALABLE)) {
	int i;
	for (i = 0; i < face->num_fixed_sizes; i++)
	    if (!FcPatternObjectAddDouble (pat, FC_PIXEL_SIZE_OBJECT,
	                                   FcGetPixelSize (face, i)))
		goto bail2;
	if (!FcPatternObjectAddBool (pat, FC_ANTIALIAS_OBJECT, FcFalse))
	    goto bail2;
    }

    FcChar8 *wrapper = NULL;

#if HAVE_FT_GET_X11_FONT_FORMAT
    /*
     * Use the (not well documented or supported) X-specific function
     * from FreeType to figure out the font format
     */
    {
	const char *font_format = FT_Get_X11_Font_Format (face);
	if (font_format) {
	    if (!FcPatternObjectAddString (pat, FC_FONTFORMAT_OBJECT, (FcChar8 *)font_format))
		goto bail2;

	    /* If this is not a SFNT font and format is CFF, then it is a standlone CFF font */
	    if (!FT_IS_SFNT (face) && !strcmp (font_format, "CFF"))
		wrapper = (FcChar8 *)"CFF";
	}
    }
#endif

    if (!FcPatternObjectAddBool (pat, FC_NAMED_INSTANCE_OBJECT, !!(id > 0xffff)))
	goto bail2;

    if (FT_IS_SFNT (face)) {
	/* If this is an SFNT wrapper, try to sniff the SFNT tag which is the
	 * first 4 bytes, to see if it is a WOFF or WOFF2 wrapper. */
	wrapper = (FcChar8 *)"SFNT";

	char buf[4];
	int  fd = FcOpen ((char *)file, O_RDONLY);
	if (fd != -1 && read (fd, buf, 4)) {
	    if (buf[0] == 'w' && buf[1] == 'O' && buf[2] == 'F') {
		if (buf[3] == 'F')
		    wrapper = (FcChar8 *)"WOFF";
		else if (buf[3] == '2')
		    wrapper = (FcChar8 *)"WOFF2";
	    }
	}
	close (fd);
    }

    if (wrapper)
	if (!FcPatternObjectAddString (pat, FC_FONT_WRAPPER_OBJECT, wrapper))
	    goto bail2;

    {
	FcPatternElt  *elt;
	FcValueListPtr l;
	int            generic_family = FC_FAMILY_UNKNOWN;

	elt = FcPatternObjectFindElt (pat, FC_FAMILY_OBJECT);
	if (elt) {
	    uint32_t memory = 0;
	    for (l = FcPatternEltValues (elt); l; l = FcValueListNext (l)) {
		FcValue v = FcValueCanonicalize (&l->value);

		if (v.type == FcTypeString) {
		    uint32_t field = FcGenericAliasGetClassification ((const char *)v.u.s);

		    if (field != 0) {
			if ((memory | field) != memory) {
			    for (int b = 0; b < 15; b++) {
				if (((memory ^ field) & (1 << b)) != 0) {
				    FcPatternObjectAddInteger (pat, FC_GENERIC_FAMILY_OBJECT, b + 1);
				}
			    }
			    memory |= field;
			}
			goto skip_generic_family;
		    } else {
			if (FcStrStrIgnoreCase (v.u.s, (FcChar8 *)"mono")) {
			    generic_family = FC_FAMILY_MONO;
			    break;
			} else if (FcStrStrIgnoreCase (v.u.s, (FcChar8 *)"sans")) {
			    generic_family = FC_FAMILY_SANS;
			    break;
			} else if (FcStrStrIgnoreCase (v.u.s, (FcChar8 *)"serif")) {
			    generic_family = FC_FAMILY_SERIF;
			    break;
			} else if (FcStrStrIgnoreCase (v.u.s, (FcChar8 *)"emoji")) {
			    generic_family = FC_FAMILY_EMOJI;
			    break;
			} else if (FcStrStrIgnoreCase (v.u.s, (FcChar8 *)"math")) {
			    generic_family = FC_FAMILY_MATH;
			    break;
			}
		    }
		}
	    }
	}
	FcPatternObjectAddInteger (pat, FC_GENERIC_FAMILY_OBJECT, generic_family);
    skip_generic_family:;
    }

    /*
     * Drop our reference to the charset
     */
    FcCharSetDestroy (cs);
    if (foundry_)
	free (foundry_);
    if (canon_file && canon_file != file)
	free (canon_file);

