	    list = NULL;
	} else {
	    if (!FcStrBufFormat (buf,
	                         "  <alias>\n"
	                         "    <family>%s</family>\n"
	                         "    <prefer><family>%s</family></prefer>\n"
	                         "  </alias>\n",
	                         gf, family)) {
