/*
 * Look for a cache file for the specified dir. Attempt
 * to use each one we find, stopping when the callback
 * indicates success
 */
static FcBool
FcDirCacheProcess (FcConfig *config, const FcChar8 *dir,
                   FcBool (*callback) (FcConfig *config, int fd, struct stat *fd_stat,
                                       struct stat *dir_stat, struct timeval *cache_mtime, void *closure),
                   void *closure, FcChar8 **cache_file_ret)
{
    int            fd = -1;
    FcChar8        cache_base[CACHEBASE_LEN];
    FcStrList     *list;
    FcChar8       *cache_dir, *d;
    struct stat    file_stat, dir_stat;
    FcBool         ret = FcFalse;
    const FcChar8 *sysroot = FcConfigGetSysRoot (config);
    struct timeval latest_mtime = (struct timeval){ 0 };

    if (sysroot)
	d = FcStrBuildFilename (sysroot, dir, NULL);
    else
	d = FcStrCopy (dir);
    if (FcStatChecksum (d, &dir_stat) < 0) {
	FcStrFree (d);
	return FcFalse;
    }
    FcStrFree (d);

    FcDirCacheBasenameMD5 (config, dir, cache_base);

    list = FcStrListCreate (config->cacheDirs);
    if (!list)
	return FcFalse;

    while ((cache_dir = FcStrListNext (list))) {
	int version;

	/* The serialized layout is compatible back to the minimum version.
	 * Search every cache directory, including older filename suffixes. */
	for (version = FC_CACHE_VERSION_NUMBER;
	     version >= FC_CACHE_MIN_COMPAT_VERSION; version--) {
	    FcChar8 compat_base[CACHEBASE_LEN];
	    FcChar8 uuid_cache_base[CACHEBASE_LEN];
	    int name;

	    FcDirCacheReplaceVersion (cache_base, compat_base, version);
	    uuid_cache_base[0] = 0;
#ifndef _WIN32
	    FcDirCacheBasenameUUID (config, dir, uuid_cache_base);
#endif
	    for (name = 0; name < 2; name++) {
		FcChar8 *cache_hashed;
		FcChar8 uuid_compat_base[CACHEBASE_LEN];
		const FcChar8 *base = compat_base;
		FcBool accepted;

		if (name) {
		    if (!uuid_cache_base[0])
			break;
		    base = FcDirCacheReplaceVersion (uuid_cache_base, uuid_compat_base, version);
		}
		if (sysroot)
		    cache_hashed = FcStrBuildFilename (sysroot, cache_dir, base, NULL);
		else
		    cache_hashed = FcStrBuildFilename (cache_dir, base, NULL);
		if (!cache_hashed)
		    continue;
		fd = FcDirCacheOpenFile (cache_hashed, &file_stat);
		accepted = FcFalse;
		if (fd >= 0) {
		    accepted = (*callback) (config, fd, &file_stat, &dir_stat, &latest_mtime, closure);
		    close (fd);
		}
		if (accepted) {
		    ret = FcTrue;
		    if (cache_file_ret) {
			if (*cache_file_ret)
			    FcStrFree (*cache_file_ret);
			*cache_file_ret = cache_hashed;
			continue;
		    }
		}
		FcStrFree (cache_hashed);
	    }
	}
    }
    FcStrListDone (list);

    if (closure)
	return !!(*((FcCache **)closure) != NULL);
    return ret;
